recipes.code:
{
  "inputs": [
    {
      "id": "anakin-api-key",
      "type": "promptString",
      "description": "Anakin API key. Get one free at https://anakin.io/dashboard (500 credits, no card required).",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@anakin-io/mcp@0.2.1"
      ],
      "env": {
        "ANAKIN_API_KEY": "${input:anakin-api-key}"
      }
    }
  }
}
